class Solution{public String multiply(String a,String b){if(a.equals("0")||b.equals("0"))return"0";int[]d=new int[a.length()+b.length()];for(int i=a.length()-1;i>=0;i--)for(int j=b.length()-1;j>=0;j--){int p=(a.charAt(i)-'0')*(b.charAt(j)-'0')+d[i+j+1];d[i+j+1]=p%10;d[i+j]+=p/10;}StringBuilder s=new StringBuilder();int i=d[0]==0?1:0;for(;i<d.length;i++)s.append(d[i]);return s.toString();}}
